    def is_balanced(group):
        count = 0
        for char in group:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            if count < 0:
                return False
        return count == 0

    # Ignore any nested groups within each other
    result = [group for group in result if is_balanced(group)]

    return result
